{
  "title": "Identity in SIGINT Reporting",
  "setting": "SIGINT reporting, before dissemination; Signals Intelligence Directorate.",
  "decider": "Signals Intelligence Director",
  "agent_recast": false,
  "recast_note": "",
  "agent": "Signals Intelligence Director",
  "agent_role": "decide",
  "situation": "A SIGINT report contains foreign-intelligence information concerning a U.S. person. The draft substitutes a generic term for the person's identity. A recipient requests the identity and says it is needed for official duties. The available assessment has not established whether the recipient needs the identity or whether the identity is necessary to understand the information or assess its importance. No consent or public-availability basis is presented, and the Signals Intelligence Director is considering the report before dissemination.",
  "question": "What should the Signals Intelligence Director do about including the U.S. person's identity in the SIGINT report?",
  "facts": [
    {
      "id": "F1",
      "kind": "authority",
      "status": "confirmed",
      "fact": "SIGINT reports are to focus solely on the activities of foreign entities and persons and their agents.",
      "spans": [
        "src:8d3b89fe949d#p16.3"
      ]
    },
    {
      "id": "F2",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Foreign-intelligence information concerning U.S. persons is generally disseminated without identifying the person, subject to the stated exception.",
      "spans": [
        "src:8d3b89fe949d#p16.3"
      ]
    },
    {
      "id": "F3",
      "kind": "authority",
      "status": "confirmed",
      "fact": "A U.S. person's identity may be included only when a stated condition is met and the appropriate approval authority determines that the recipient needs the identity for official duties.",
      "spans": [
        "src:8d3b89fe949d#p16.4"
      ]
    },
    {
      "id": "F4",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Consent is one permissible basis for identifying a U.S. person, and it requires an executed consent form.",
      "spans": [
        "src:8d3b89fe949d#p16.5"
      ]
    },
    {
      "id": "F5",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Information derived from unclassified information available to the general public is one permissible basis for identifying a U.S. person.",
      "spans": [
        "src:8d3b89fe949d#p16.6"
      ]
    },
    {
      "id": "F6",
      "kind": "authority",
      "status": "confirmed",
      "fact": "A U.S. person's identity may be included when it is necessary to understand the foreign-intelligence information or assess its importance.",
      "spans": [
        "src:8d3b89fe949d#p16.7"
      ]
    },
    {
      "id": "F7",
      "kind": "authority",
      "status": "confirmed",
      "fact": "In cases not assigned to other approval authorities, prior approval for release may be given by the Signals Intelligence Director or specified designees.",
      "spans": [
        "src:8d3b89fe949d#p18.6",
        "src:8d3b89fe949d#p18.7"
      ]
    },
    {
      "id": "F8",
      "kind": "situation",
      "status": "confirmed",
      "fact": "In this scenario, the report concerns a U.S. person and its draft uses a generic term in place of the person's identity.",
      "spans": []
    },
    {
      "id": "F9",
      "kind": "situation",
      "status": "assessed",
      "fact": "In this scenario, a recipient requests the identity and claims an official-duty need, but the approval determination of that need is pending.",
      "spans": []
